                    <span class="required" aria-hidden="true">*</span>
                  </legend>
                  <p class="help" id="notification-help">Choose exactly one answer.</p>
                  <div class="options" role="presentation">
                    ${RadioOption({ id: "notif-email", value: "email", label: "Email" })}
                    ${RadioOption({ id: "notif-sms", value: "sms", label: "SMS" })}
                    ${RadioOption({ id: "notif-push", value: "push", label: "Push Notifications" })}
                  </div>
                </fieldset>
